import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.BzWmN0d8.js";const g=JSON.parse('{"title":"基准测试","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/benchmarks.md","filePath":"zh/guide/benchmarks.md","lastUpdated":1788425513000}'),s={name:"zh/guide/benchmarks.md"};function r(i,t,c,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="基准测试" tabindex="-1">基准测试 <a class="header-anchor" href="#基准测试" aria-label="Permalink to &quot;基准测试&quot;">​</a></h1><p><code>lograil</code> 的设计目标之一是在高频调用路径上保持极低开销。本页介绍如何自行测量吞吐量， 并记录我们为保持核心高性能所做的各项优化。</p><h2 id="运行基准测试" tabindex="-1">运行基准测试 <a class="header-anchor" href="#运行基准测试" aria-label="Permalink to &quot;运行基准测试&quot;">​</a></h2><p>基准测试基于 <a href="https://vitest.dev/api/#benchmark" target="_blank" rel="noreferrer">vitest bench</a> 编写，从仓库根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 或： npx vitest bench --run</span></span></code></pre></div><p>每条用例报告的是 <strong>hz（每秒操作数，越高越好）</strong> 以及延迟分位数（如 p50/p99）。基准套件通过配合 <strong>什么都不做的空传输器</strong> 来把 logger 核心与传输层 I/O 隔离，因此数据反映的是 格式化、过滤与日志条目构建的开销，而非磁盘/控制台写入成本。</p><h2 id="吞吐量-参考数据" tabindex="-1">吞吐量（参考数据） <a class="header-anchor" href="#吞吐量-参考数据" aria-label="Permalink to &quot;吞吐量（参考数据）&quot;">​</a></h2><p>在 Node.js v24（x64）下，配合 no-op 传输器测得。数值会随机器与运行波动，请将其 视为<strong>相对对比</strong>而非硬性承诺。在你的机器上重新运行 <code>npm run bench</code> 可得到权威数据。</p><table tabindex="0"><thead><tr><th>场景</th><th>吞吐量</th></tr></thead><tbody><tr><td><code>emit</code> — 被过滤掉的 debug（提前返回）</td><td>~19.5M ops/s</td></tr><tr><td><code>emit</code> — <code>info</code> + 原样格式化器（identity）（无格式化开销）</td><td>~3.0M ops/s</td></tr><tr><td><code>emit</code> — <code>info</code> + 行格式化器</td><td>~1.46M ops/s</td></tr><tr><td>行格式化器（单独调用）</td><td>~1.96M ops/s</td></tr><tr><td>JSON 格式化器（单独调用）</td><td>~1.23M ops/s</td></tr></tbody></table><h2 id="与-pino-的对比" tabindex="-1">与 <code>pino</code> 的对比 <a class="header-anchor" href="#与-pino-的对比" aria-label="Permalink to &quot;与 `pino` 的对比&quot;">​</a></h2><p><code>pino</code> 是<strong>纯 Node.js</strong> 场景下极快的标杆日志库。<code>lograil</code> 面向不同场景——Electron （主进程 + 渲染进程）与 Web——因此单纯的纯 Node 吞吐比拼只是故事的一半。下表是<strong>能力</strong> 对比；要拿原始 ops/s 对比，请在本机运行 <code>npm run bench</code> 并与 <code>pino</code> 比较。</p><table tabindex="0"><thead><tr><th>维度</th><th><code>lograil</code></th><th><code>pino</code></th></tr></thead><tbody><tr><td>运行时</td><td>Electron 主进程、Electron 渲染进程、Web、Node</td><td>仅 Node</td></tr><tr><td>跨进程日志</td><td>一等公民（<code>ElectronIpcTransport</code>，结构化克隆）</td><td>需自行 IPC</td></tr><tr><td>结构化 <code>context</code>/<code>metadata</code> + <code>args</code></td><td>内置，冻结不可变条目</td><td>绑定对象 / <code>child</code> 绑定</td></tr><tr><td>处理器 / 插件管道</td><td>内置（<code>Filter</code>/<code>Processor</code>/<code>Plugin</code>）</td><td>经 transports / 自定义</td></tr><tr><td>内置脱敏与序列化器</td><td><code>createRedactProcessor</code> / <code>createDefaultSerializers</code></td><td><code>pino-secret</code> / 自定义</td></tr><tr><td>OTel trace 关联</td><td><code>createOtelTracePlugin</code></td><td>外部方案</td></tr><tr><td>格式</td><td>JSON（<code>flatten</code> 选项）+ 行格式</td><td>JSON、pretty、自定义</td></tr><tr><td>纯 Node 吞吐</td><td>很快（见上表）</td><td>通常更快（C 层缓冲）</td></tr><tr><td>浏览器 / 打包安全</td><td>是（Node 内置模块经 <code>shims</code> 层 + <code>browser</code> 字段替换为 stub；并有打包器集成测试验证）</td><td>否</td></tr></tbody></table><h3 id="如何选型" tabindex="-1">如何选型 <a class="header-anchor" href="#如何选型" aria-label="Permalink to &quot;如何选型&quot;">​</a></h3><ul><li><strong>选 <code>pino</code>：</strong> 仅从 Node 服务端打日志，绝不碰 Electron/浏览器，且要绝对最大的原始吞吐、 最少机制。</li><li><strong>选 <code>lograil</code>：</strong> 只要你需要以下任意一项——Electron 主↔渲染日志转发、Web 运行时支持、 结构化 <code>context</code>/<code>metadata</code> 模型、插件/处理器管道、内置脱敏与序列化器、OTel trace 关联， 或带冻结不可变条目契约的异步每-transport 队列。</li></ul><p>也可以混用：高频调用路径的 Node 服务用 <code>pino</code>，与其通信的 Electron 外壳用 <code>lograil</code>。</p><h2 id="这些结果的发布位置" tabindex="-1">这些结果的发布位置 <a class="header-anchor" href="#这些结果的发布位置" aria-label="Permalink to &quot;这些结果的发布位置&quot;">​</a></h2><p>上面的数字已写入本页，并<strong>随文档一同发布</strong>——每次 <code>yarn docs:build</code>（以及每次发版部署的 版本化文档）都包含它们。要更新，运行 <code>npm run bench</code>，把 <code>hz</code>/延迟输出贴回本表即可。它们 刻意做成<strong>参考值</strong>：请在本机重跑以获得权威数字。</p><h2 id="我们做了哪些优化" tabindex="-1">我们做了哪些优化 <a class="header-anchor" href="#我们做了哪些优化" aria-label="Permalink to &quot;我们做了哪些优化&quot;">​</a></h2><p>库内置了若干高频调用路径优化，且<strong>全部保持行为不变</strong>，仅提升性能。</p><ol><li><strong>无插件时跳过异步路径。</strong> 当没有任何插件注册 <code>onEntry</code> 拦截器时，<code>Logger</code> 直接同步输出，完全绕开 <code>Promise</code>/写入队列机制（<code>PluginManager.hasEntryInterceptors()</code> 判断 + 独立的 <code>dispatch</code> 分支）。这正是上表&quot;被过滤掉&quot;与&quot;原样格式化器（identity）&quot;两行之间差距的来源。</li><li><strong>缓存合并后的过滤器。</strong> <code>Pipeline</code> 将所有过滤器编译为单个合并后的过滤条件（<code>cachedFilter</code>） 并复用，避免在每次日志上重复遍历过滤器列表。</li><li><strong><code>safeStringify</code> 快速路径。</strong> 纯 JSON 可序列化数据（对象/数组/基本类型，含 <code>undefined</code>） 直接走原生 <code>JSON</code> 方法，跳过仅为处理 <code>Error</code>、循环引用与 <code>BigInt</code> 而存在的自定义 替换函数，使 JSON 格式化器在最常见场景下保持高速。</li><li><strong>行格式化器中的 <code>isEmptyRecord</code>。</strong> 用廉价的 <code>for…in</code> 存在性判断来决策是否渲染 <code>context</code>/<code>metadata</code>，取代会分配数组并遍历的 <code>Object.keys(ctx).length</code>。</li><li><strong>共享冻结的空上下文。</strong> 当 store 为空时，<code>ContextStore.get()</code> 返回同一个共享的冻结 空对象，避免在高频率的&quot;无上下文&quot;路径上做逐次克隆与分配，且调用方无法修改它。</li><li><strong>时间戳复用单个 <code>Date</code>。</strong> <code>buildEntry</code> 通过复用的单个 <code>Date</code>（读取 UTC 字段）来格式化 ISO-8601 时间戳，因此每条日志都不会新分配 <code>Date</code> 对象，仅构建最终字符串。</li></ol><h2 id="尽早过滤是最划算的优化" tabindex="-1">尽早过滤是最划算的优化 <a class="header-anchor" href="#尽早过滤是最划算的优化" aria-label="Permalink to &quot;尽早过滤是最划算的优化&quot;">​</a></h2><p>最大的单项提速其实是不打日志：级别门槛在流水线之前运行，低于当前阈值的 <code>debug</code> 调用会被直接丢弃。生产环境请尽可能把日志级别调高。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { logger } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;lograil&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setLevel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;warn&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// info/debug 永远不会进入流水线</span></span></code></pre></div>',23)])])}const k=e(s,[["render",r]]);export{g as __pageData,k as default};
